create extension if not exists pgcrypto;
create table if not exists public.departments(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,owner_only boolean not null default false,created_at timestamptz not null default now());
insert into public.departments(name,slug,owner_only) values('Front Desk / Reception','front-desk',false),('Housekeeping / Rooms','housekeeping',false),('Restaurant and Kitchen','restaurant-kitchen',false),('Bar','bar',false),('Maintenance and Cleaning','maintenance-cleaning',false),('Security','security',false),('Accounts / Finance','accounts-finance',true) on conflict(slug) do nothing;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text,role text not null check(role in('owner','manager','staff')),department_id uuid references public.departments(id),avatar_url text,is_active boolean not null default true,created_at timestamptz not null default now(),constraint manager_department_required check(role<>'manager' or department_id is not null));
create table if not exists public.rooms(id uuid primary key default gen_random_uuid(),room_number text not null unique,room_type text not null,nightly_rate numeric(14,2) not null default 0 check(nightly_rate>=0),facilities text[] not null default '{}',image_urls text[] not null default '{}',status text not null default 'available' check(status in('available','occupied','dirty','cleaning','maintenance','booked')),is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.bookings(id uuid primary key default gen_random_uuid(),guest_name text not null,guest_email text,guest_phone text not null,check_in date not null,check_out date not null,guests int not null default 1 check(guests>0),room_type text,room_id uuid references public.rooms(id),status text not null default 'pending' check(status in('pending','confirmed','checked_in','checked_out','cancelled')),payment_option text not null default 'pay_at_hotel' check(payment_option in('deposit','pay_at_hotel')),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(check_out>check_in));
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),booking_id uuid references public.bookings(id),amount numeric(14,2) not null check(amount>=0),currency text not null default 'UGX',provider text not null default 'pesapal',provider_reference text unique,status text not null default 'pending' check(status in('pending','completed','failed','refunded')),created_at timestamptz not null default now());
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),title text not null,amount numeric(14,2) not null check(amount>=0),department_id uuid references public.departments(id),created_by uuid references public.profiles(id),approval_status text not null default 'pending' check(approval_status in('pending','approved','rejected')),approved_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.attendance(id uuid primary key default gen_random_uuid(),staff_id uuid not null references public.profiles(id),clock_in timestamptz not null default now(),clock_out timestamptz,status text not null default 'clocked_in' check(status in('clocked_in','completed','absent')));
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),title text not null,description text,department_id uuid references public.departments(id),assigned_to uuid references public.profiles(id),due_date date not null default current_date,status text not null default 'todo' check(status in('todo','in_progress','done')),completed_at timestamptz,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.inventory_items(id uuid primary key default gen_random_uuid(),name text not null,department_id uuid references public.departments(id),quantity numeric(14,2) not null default 0,unit text not null default 'units',low_stock_threshold numeric(14,2) not null default 0,is_active boolean not null default true,updated_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.staff_leave(id uuid primary key default gen_random_uuid(),staff_id uuid not null references public.profiles(id),starts_on date not null,ends_on date not null,reason text,status text not null default 'pending' check(status in('pending','approved','rejected')),reviewed_by uuid references public.profiles(id),created_at timestamptz not null default now(),check(ends_on>=starts_on));
create or replace function public.current_user_role() returns text language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() and is_active=true limit 1 $$;
create or replace function public.current_user_department() returns uuid language sql stable security definer set search_path=public as $$ select department_id from public.profiles where id=auth.uid() and is_active=true limit 1 $$;
create or replace function public.is_owner() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_user_role()='owner',false) $$;
alter table public.departments enable row level security;alter table public.profiles enable row level security;alter table public.rooms enable row level security;alter table public.bookings enable row level security;alter table public.payments enable row level security;alter table public.expenses enable row level security;alter table public.attendance enable row level security;alter table public.tasks enable row level security;alter table public.inventory_items enable row level security;alter table public.audit_logs enable row level security;alter table public.staff_leave enable row level security;
create policy "departments scoped read" on public.departments for select to authenticated using(not owner_only or public.is_owner() or id=public.current_user_department());
create policy "owner department control" on public.departments for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy "profile read scope" on public.profiles for select to authenticated using(public.is_owner() or id=auth.uid() or (public.current_user_role()='manager' and department_id=public.current_user_department()));
create policy "owner profile control" on public.profiles for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy "manager update department staff" on public.profiles for update to authenticated using(public.current_user_role()='manager' and department_id=public.current_user_department() and role='staff') with check(public.current_user_role()='manager' and department_id=public.current_user_department() and role='staff');
create policy "staff public room catalogue" on public.rooms for select to anon using(is_active=true);
create policy "staff read rooms" on public.rooms for select to authenticated using(true);
create policy "owner room control" on public.rooms for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy "public create pending booking" on public.bookings for insert to anon,authenticated with check(status='pending');
create policy "owner and reception read bookings" on public.bookings for select to authenticated using(public.is_owner() or public.current_user_department()=(select id from public.departments where slug='front-desk'));
create policy "owner and reception update bookings" on public.bookings for update to authenticated using(public.is_owner() or public.current_user_department()=(select id from public.departments where slug='front-desk')) with check(public.is_owner() or public.current_user_department()=(select id from public.departments where slug='front-desk'));
create policy "owner read payments" on public.payments for select to authenticated using(public.is_owner());
create policy "owner payment control" on public.payments for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy "owner expense control" on public.expenses for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy "manager read department expenses" on public.expenses for select to authenticated using(public.current_user_role()='manager' and department_id=public.current_user_department());
create policy "owner read attendance" on public.attendance for select to authenticated using(public.is_owner());
create policy "staff read own attendance" on public.attendance for select to authenticated using(staff_id=auth.uid());
create policy "staff clock in" on public.attendance for insert to authenticated with check(staff_id=auth.uid());
create policy "staff clock out" on public.attendance for update to authenticated using(staff_id=auth.uid()) with check(staff_id=auth.uid());
create policy "manager read department attendance" on public.attendance for select to authenticated using(public.current_user_role()='manager' and staff_id in(select id from public.profiles where department_id=public.current_user_department()));
create policy "owner task control" on public.tasks for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy "manager department task control" on public.tasks for all to authenticated using(public.current_user_role()='manager' and department_id=public.current_user_department()) with check(public.current_user_role()='manager' and department_id=public.current_user_department());
create policy "staff read assigned tasks" on public.tasks for select to authenticated using(assigned_to=auth.uid());
create policy "staff update assigned tasks" on public.tasks for update to authenticated using(assigned_to=auth.uid()) with check(assigned_to=auth.uid());
create policy "owner inventory control" on public.inventory_items for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy "manager inventory control" on public.inventory_items for all to authenticated using(public.current_user_role()='manager' and department_id=public.current_user_department()) with check(public.current_user_role()='manager' and department_id=public.current_user_department());
create policy "owner audit read" on public.audit_logs for select to authenticated using(public.is_owner());
create policy "actor audit insert" on public.audit_logs for insert to authenticated with check(actor_id=auth.uid());
create policy "owner leave control" on public.staff_leave for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy "staff read own leave" on public.staff_leave for select to authenticated using(staff_id=auth.uid());
create policy "staff create own leave" on public.staff_leave for insert to authenticated with check(staff_id=auth.uid());
create policy "manager read department leave" on public.staff_leave for select to authenticated using(public.current_user_role()='manager' and staff_id in(select id from public.profiles where department_id=public.current_user_department()));
-- Bootstrap owner: create the owner Auth user first, then insert/update its profile with role='owner'.
